class ArtPainter extends CustomPainter { ArtPainter(this.points, this.color, this.erase); final List<Offset?> points; final Color color; final bool erase; @override void paint(Canvas canvas, Size size) { for (int i=0;i<points.length;i++) { final p=points[i]; if (p == null) { continue; } final next = i+1<points.length ? points[i+1] : null; final paint=Paint()..color=erase?Colors.white:color..strokeWidth=erase?24:6..strokeCap=StrokeCap.round..strokeJoin=StrokeJoin.round..style=PaintingStyle.stroke; if (next != null) { canvas.drawLine(p,next,paint); } else { canvas.drawCircle(p, erase?12:3, Paint()..color=erase?Colors.white:color); } } } @override bool shouldRepaint(covariant ArtPainter oldDelegate)=>true; }
class ConfettiPainter extends CustomPainter { ConfettiPainter(this.progress); final double progress; @override void paint(Canvas canvas, Size size) { final paint=Paint(); final colors=[pink,yellow,green,purple,orange,Colors.blue]; for(int i=0;i<42;i++){ final x=(i*47.0)%size.width; final y=((i*61.0)+progress*size.height*1.7)%size.height; paint.color=colors[i%colors.length].withValues(alpha: 1-progress*.35); canvas.save(); canvas.translate(x,y); canvas.rotate(progress*math.pi*4+i); canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero,width: 7,height: 12),const Radius.circular(2)),paint); canvas.restore(); } } @override bool shouldRepaint(covariant ConfettiPainter oldDelegate)=>oldDelegate.progress!=progress; }
